package common

import("bytes";"encoding/json";"fmt";"net/http";"strings")
type TeamsAdapter struct{Token,ServiceURL string;Client *http.Client}
func(a TeamsAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){from,_:=payload["from"].(map[string]any);user,_:=from["id"].(string);conversation,_:=payload["conversation"].(map[string]any);conv,_:=conversation["id"].(string);if user==""||conv==""{return InboundEvent{},fmt.Errorf("Teams activity has no sender or conversation")};event:=InboundEvent{Platform:"teams",UserID:user,ReplyTarget:conv,ContentType:"text"};event.Text,_=payload["text"].(string);if attachments,ok:=payload["attachments"].([]any);ok&&len(attachments)>0{attachment,_:=attachments[0].(map[string]any);event.ContentType="file";event.MediaURL,_=attachment["contentUrl"].(string)};return event,nil}
func(a TeamsAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{body:=map[string]any{"type":"message","text":message.Text};if message.Type!="text"&&message.MediaURL!=""{body["attachments"]=[]map[string]string{{"contentType":"application/octet-stream","contentUrl":message.MediaURL,"name":"attachment"}}};data,_:=json.Marshal(body);req,_:=http.NewRequest(http.MethodPost,strings.TrimRight(a.ServiceURL,"/")+"/v3/conversations/"+event.ReplyTarget+"/activities",bytes.NewReader(data));req.Header.Set("Authorization","Bearer "+a.Token);req.Header.Set("Content-Type","application/json");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Teams API returned %s",resp.Status)}};return nil}
